// Build Context (TechQA): the top 6 chunks.
const SYSTEM = ("Support triage agent for IBM technical support, grounded in real Technotes ({{ $now.toFormat('yyyy-MM-dd') }}). Use ONLY search_techqa_docs context to answer - do not invent configuration values, file paths, commands, or troubleshooting steps beyond what the retrieved context actually states, even if you know the general answer from training. No answer found -> try resolution_specialist once before giving up. cited_source = real doc path from context, or empty string "" if none - never invent one, never write an explanatory sentence there. needs_handoff=true only if deferring entirely without trying. If resolution_specialist says it cannot answer / needs review, set needs_human_review=true, confidence="low". No supporting context -> confidence="low", say so.".replace("{{ $now.toFormat('yyyy-MM-dd') }}", new Date().toISOString().slice(0, 10)) + "

Return only a JSON object with the keys: answer (string), confidence ("high", "medium" or "low"), needs_handoff (boolean), needs_human_review (boolean), cited_source (string). No text outside the JSON.");
const hits = ($input.first().json.result || []);
const question = $('Finalize Sanitized Text').first().json.normalized_text;
if (!hits.length) {
  return [{ json: { system: SYSTEM, user: 'Question:
' + question + '

Search results (the documentation passages found for this question):
(no passages were found)', retrieval_problem: 'search_empty' } }];
}
const context = hits.map((h) => '[' + h.payload.source + ']
' + h.payload.text).join('

---

');
return [{ json: { system: SYSTEM, user: 'Question:
' + question + '

Search results (the documentation passages found for this question):
' + context, retrieval_problem: null } }];

// Extracts the model's JSON reply into { output }. An unusable reply throws, so the error branch answers 503. An empty search becomes a hand-off.
const resp = $input.first().json;
if ($('Build Context').first().json.retrieval_problem === 'search_empty') {
  return [{ json: { output: { answer: '', confidence: 'low', needs_handoff: true, needs_human_review: true, cited_source: '' }, retrieval_problem: 'search_empty', usage: null } }];
}
const raw =resp && resp.choices && resp.choices[0] && resp.choices[0].message ? (resp.choices[0].message.content || '') : '';
const m = String(raw).match(/\{[\s\S]*\}/);
let d = null;
try { d = m ? JSON.parse(m[0]) : null; } catch (e) { d = null; }
if (!d || typeof d !== 'object') {
  throw new Error('answer model returned no usable JSON (' + (resp && (resp.error || resp.message || resp.status) ? JSON.stringify(resp.error || resp.message || resp.status).slice(0, 160) : 'empty reply') + ')');
}
const conf = ['high', 'medium', 'low'].includes(d.confidence) ? d.confidence : 'low';
const answer = typeof d.answer === 'string' ? d.answer : '';
const out = { answer, confidence: answer ? conf : 'low', needs_handoff: d.needs_handoff === true, needs_human_review: d.needs_human_review === true, cited_source: typeof d.cited_source === 'string' ? d.cited_source : '' };
return [{ json: { output: out, retrieval_problem: $('Build Context').first().json.retrieval_problem || null, usage: resp.usage || null } }];
